function wordCount(post) {
  const text = [...post.body, ...(post.faq || []).flatMap(({ q, a }) => [q, a])]
    .map((item) => (Array.isArray(item) ? item.join(' ') : typeof item === 'string' ? item : ''))
    .join(' ')
    .replace(/@image:\d+/g, '')
    .replace(/<[^>]*>/g, ' ')
  return text.trim().split(/\s+/).filter(Boolean).length
}

export const seoBlogPostsThird = articleDrafts.map((draft) => {
  const images = blogImages(draft.imageTopic, draft.flip)
  const expandedBody = [...draft.body]
  expandedBody.splice(expandedBody.length - 1, 0, ...articleExpansions[draft.slug])
  const body = expandedBody.map((item) => {
    if (typeof item !== 'string' || !item.startsWith('@image:')) return item
    const index = Number(item.slice('@image:'.length))
    return images[index]
  })

  const internalLinkOpportunities = [
    ...new Set(
      body
        .filter((item) => typeof item === 'string')
        .flatMap((text) => [...text.matchAll(/\[[^\]]+\]\((\/[^)]+)\)/g)].map((match) => match[1]))
    ),
  ]

  const post = {
    slug: draft.slug,
    title: draft.title,
    metaTitle: draft.metaTitle,
    metaDescription: draft.metaDescription,
    keyword: draft.keyword,
    secondaryKeywords: draft.secondaryKeywords,
    longTailKeywords: draft.longTailKeywords,
    excerpt: draft.excerpt,
    date: published,
    updated: published,
    category: 'Guides',
    images,
    tags: draft.tags,
    body,
    faq: draft.faq,
    searchIntent: 'Informational, with a transactional play intent',
    internalLinkOpportunities,
    suggestedRelatedArticles: internalLinkOpportunities.filter((url) => url.startsWith('/blogs/')),
    schemaRecommendations: ['BlogPosting', 'BreadcrumbList', 'FAQPage for visible questions only'],
    socialTitle: draft.title,
    socialDescription: draft.metaDescription,
  }

  return {
    ...post,
    wordCount: wordCount(post),
  }
})
